INSERT INTO `py_announcements` VALUES (5, '欢迎使用新闻公告管理系统', '<p>这是一个功能完善的新闻公告管理系统，支持公告的发布、编辑、删除等操作。管理员可以在后台管理公告，用户可以在前台查看公告。</p><p><img src=\"/upload/be2ba695cf1e4371b2d9f125056b2f45.jpg\"></p>', '这是一个功能完善的新闻公告管理系统，支持公告的发布、编辑、删除等操作。管理员可以在后台管理公告，用户可以在前台查看公告', 'admin', 1, 1, 1, 11, '2025-09-26 18:26:07', '2026-04-22 02:49:48');
INSERT INTO `py_announcements` VALUES (6, '系统维护通知', '<p>系统将于本周六凌晨2:00-4:00进行维护升级，期间可能影响正常使用，请提前做好准备。</p>', '请提前做好准备请提前做好准备', 'admin', 1, 1, 1, 8, '2025-09-26 18:26:07', '2025-10-14 13:46:49');
INSERT INTO `py_announcements` VALUES (7, '新功能上线公告', '<p>我们很高兴地宣布，新闻公告管理系统新增了以下功能：\n1. 支持富文本编辑\n2. 支持公告置顶\n3. 支持状态管理\n4. 优化了用户界面\n\n感谢您的使用！</p>', '我们很高兴地宣布，新闻公告管理系统新增了以下功能', 'admin', 1, 1, 0, 0, '2025-09-26 18:26:07', '2025-09-29 17:55:09');
INSERT INTO `py_announcements` VALUES (8, '用户使用指南', '为了更好地使用本系统，请参考以下使用指南：\n\n1. 管理员功能：\n   - 登录后台管理系统\n   - 可以发布、编辑、删除公告\n   - 可以设置公告状态和置顶\n\n2. 用户功能：\n   - 在前台查看已发布的公告\n   - 支持按时间排序\n   - 置顶公告优先显示', '为了更好地使用本系统，请参考以下使用指南：\n\n1. 管理员功能：\n   - 登录后台管理系统\n   - 可以发布、编辑、删除公告\n   - 可以设置公告状态和置顶\n\n2. 用户功能：\n   - 在前台...', '系统管理员', 1, 0, 0, 0, '2025-09-26 18:26:07', '2025-09-29 16:12:52');
INSERT INTO `py_announcements` VALUES (9, '草稿测试公告', '这是一个草稿状态的公告，只有管理员可以看到。', '这是一个草稿状态的公告，只有管理员可以看到。', '系统管理员', 1, 0, 0, 0, '2025-09-26 18:26:07', '2025-09-29 16:12:52');
