INSERT INTO `py_customer_communication` VALUES (1, 2, 1, 'phone', '春季新品推荐', '向客户介绍了本季新上架的鲜花品种，包括郁金香、风信子等春季特色花卉，客户表示很感兴趣。', 'new_product', '客户对郁金香很感兴趣，希望了解更多养护知识', '2026-03-15 10:00:00', 'pending', 1, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (2, 24, 1, 'wechat', '母亲节促销活动通知', '通过微信向客户推送母亲节特惠活动信息，康乃馨礼盒8折优惠，客户已查看消息。', 'promotion', '客户已下单购买康乃馨礼盒', '2026-05-10 14:00:00', 'completed', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:34:01');
INSERT INTO `py_customer_communication` VALUES (3, 4, 1, 'email', '客户满意度调查', '发送邮件收集客户对上次购买体验的反馈，了解产品质量和配送服务的满意度。', 'feedback', '客户对产品质量满意，但希望配送速度能更快', '2026-03-20 09:00:00', 'completed', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (4, 5, 1, 'phone', '订单跟进回访', '针对客户上周的订单进行回访，确认收货情况和产品满意度，解答养护问题。', 'follow_up', '客户已收货，对产品很满意，咨询了花卉养护技巧', NULL, 'completed', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (5, 2, 1, 'wechat', '情人节特别推荐', '提前一个月向VIP客户推荐情人节玫瑰礼盒，提供预定优惠和定制服务。', 'holiday', '客户预定了99朵红玫瑰礼盒，要求2月14日送达', '2026-02-10 10:00:00', 'pending', 1, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (6, 6, 1, 'qq', '产品咨询解答', '客户咨询多肉植物的养护方法和适合的土壤类型，提供了详细的养护指南。', 'consultation', '客户表示很有帮助，考虑购买多肉组合套装', '2026-03-12 15:00:00', 'pending', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (7, 7, 1, 'email', '会员专属优惠通知', '向会员客户发送专属优惠券，全场商品满200减30，有效期一个月。', 'promotion', '客户已领取优惠券', '2026-04-01 10:00:00', 'completed', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (8, 8, 1, 'phone', '新客户欢迎致电', '对新注册客户进行欢迎致电，介绍平台特色和会员权益，解答疑问。', 'consultation', '客户对平台印象良好，表示会尝试购买', '2026-03-18 11:00:00', 'pending', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
INSERT INTO `py_customer_communication` VALUES (9, 2, 1, 'wechat', '生日祝福及优惠', '在客户生日当天发送祝福消息，并赠送生日专属优惠券。', 'other', '客户很感动，表示会继续支持', NULL, 'completed', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:34:12');
INSERT INTO `py_customer_communication` VALUES (10, 4, 1, 'email', '秋季养护指南推送', '向客户推送秋季花卉养护指南，包括浇水频率、光照要求等专业建议。', 'other', '客户表示内容很实用，收藏了邮件', '2026-09-01 10:00:00', 'pending', 0, NULL, '2026-03-07 15:26:25', '2026-03-07 15:26:25');
