-- Table structure for py_cart
-- ----------------------------
DROP TABLE IF EXISTS `py_cart`;
CREATE TABLE `py_cart`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '购物车ID',
  `userId` int(11) NOT NULL COMMENT '用户ID',
  `productId` int(11) NOT NULL COMMENT '商品ID',
  `skuId` int(11) DEFAULT NULL COMMENT '规格ID',
  `quantity` int(11) NOT NULL DEFAULT 1 COMMENT '数量',
  `price` decimal(10, 2) NOT NULL COMMENT '单价',
  `createTime` datetime(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_product_sku`(`userId`, `productId`, `skuId`) USING BTREE,
  INDEX `idx_userId`(`userId`) USING BTREE,
  INDEX `idx_productId`(`productId`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '购物车表' ROW_FORMAT = Dynamic;

