-- Table structure for py_category
-- ----------------------------
DROP TABLE IF EXISTS `py_category`;
CREATE TABLE `py_category`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `supplierId` int(11) DEFAULT NULL COMMENT '供应商ID（为NULL表示平台公共分类）',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `parentId` int(11) DEFAULT 0 COMMENT '父分类ID，0为顶级分类',
  `level` tinyint(2) DEFAULT 1 COMMENT '分类层级',
  `sort` int(11) DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) DEFAULT 1 COMMENT '状态：1启用，0禁用',
  `createTime` datetime(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parentId`(`parentId`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_supplierId`(`supplierId`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品分类表' ROW_FORMAT = Dynamic;

