-- ----------------------------
-- Table structure for py_complaint
-- ----------------------------
DROP TABLE IF EXISTS `py_complaint`;
CREATE TABLE `py_complaint`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '投诉ID',
  `userId` int(11) NOT NULL COMMENT '投诉用户ID',
  `complaintNo` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投诉单号（唯一）',
  `type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'platform' COMMENT '投诉类型：order-订单投诉, product-商品投诉, service-服务投诉, platform-平台投诉, other-其他',
  `orderId` int(11) DEFAULT NULL COMMENT '关联订单ID（type=order时填写）',
  `orderNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联订单号',
  `productId` int(11) DEFAULT NULL COMMENT '关联商品ID（type=product时填写）',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投诉标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '投诉内容',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '投诉图片（JSON数组，最多5张）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '处理状态：pending-待处理, processing-处理中, resolved-已解决, rejected-已驳回, closed-已关闭',
  `priority` tinyint(1) NOT NULL DEFAULT 1 COMMENT '优先级：1-普通, 2-紧急, 3-非常紧急',
  `replyContent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '客服回复内容',
  `replyUserId` int(11) DEFAULT NULL COMMENT '回复客服/管理员ID',
  `replyTime` datetime(0) DEFAULT NULL COMMENT '回复时间',
  `rating` tinyint(1) DEFAULT NULL COMMENT '用户评分（1-5星，解决后评价）',
  `ratingComment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户评价内容',
  `ratingTime` datetime(0) DEFAULT NULL COMMENT '评价时间',
  `resolvedTime` datetime(0) DEFAULT NULL COMMENT '解决时间',
  `createTime` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_complaintNo`(`complaintNo`) USING BTREE,
  INDEX `idx_userId`(`userId`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_orderId`(`orderId`) USING BTREE,
  INDEX `idx_productId`(`productId`) USING BTREE,
  INDEX `idx_createTime`(`createTime`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户投诉反馈表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of py_complaint
-- ----------------------------

-- ----------------------------
-- Table structure for py_customer_communication
-- ----------------------------
DROP TABLE IF EXISTS `py_customer_communication`;
CREATE TABLE `py_customer_communication`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `userId` int(11) NOT NULL COMMENT '客户用户ID',
  `salesId` int(11) DEFAULT NULL COMMENT '销售人员ID',
  `communicationType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '沟通方式：phone-电话, email-邮件, wechat-微信, qq-QQ, other-其他',
  `communicationTitle` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '沟通主题',
  `communicationContent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '沟通内容',
  `communicationPurpose` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '沟通目的：new_product-新品推荐, promotion-促销活动, holiday-节日推荐, feedback-反馈收集, consultation-咨询解答, follow_up-跟进回访, other-其他',
  `customerFeedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '客户反馈',
  `nextFollowUpTime` datetime(0) DEFAULT NULL COMMENT '下次跟进时间',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'pending' COMMENT '状态：pending-待跟进, completed-已完成, cancelled-已取消',
  `isImportant` tinyint(1) DEFAULT 0 COMMENT '是否重要：0-否, 1-是',
  `attachments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '附件（JSON格式存储多个附件URL）',
  `createTime` datetime(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId`(`userId`) USING BTREE,
  INDEX `idx_salesId`(`salesId`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_createTime`(`createTime`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户沟通记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of py_customer_communication
-- ----------------------------

-- ----------------------------
-- Table structure for py_order
-- ----------------------------
DROP TABLE IF EXISTS `py_order`;
CREATE TABLE `py_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `supplierId` int(11) DEFAULT NULL COMMENT '供应商ID（订单所属供应商）',
  `orderNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `userId` int(11) NOT NULL COMMENT '用户ID',
  `totalAmount` decimal(10, 2) NOT NULL COMMENT '订单总金额',
  `payAmount` decimal(10, 2) NOT NULL COMMENT '实付金额',
  `discountAmount` decimal(10, 2) DEFAULT 0.00 COMMENT '优惠金额',
  `couponId` int(11) DEFAULT NULL COMMENT '使用的优惠券ID',
  `couponAmount` decimal(10, 2) DEFAULT 0.00 COMMENT '优惠券抵扣金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'pending' COMMENT '订单状态：pending-待付款，paid-已付款，shipped-已发货，delivered-已送达，completed-已完成，cancelled-已取消',
  `payStatus` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'unpaid' COMMENT '支付状态：unpaid-未支付，paid-已支付，refunded-已退款',
  `payMethod` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付方式：alipay-支付宝，wechat-微信，bank-银行卡',
  `payTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时间',
  `shippingStatus` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'unshipped' COMMENT '发货状态：unshipped-未发货，shipped-已发货，delivered-已送达',
  `shippingTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货时间',
  `trackingNumber` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '物流单号',
  `shippingCompany` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '物流公司',
  `logisticsInfo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '物流跟踪信息（支持多行文本）',
  `deliveryTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '送达时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单备注',
  `receiverName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人姓名',
  `receiverPhone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人电话',
  `receiverProvince` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货省份',
  `receiverCity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货城市',
  `receiverDistrict` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货区县',
  `receiverAddress` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货详细地址',
  `receiverPostcode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货邮政编码',
  `createTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建时间',
  `updateTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_orderNo`(`orderNo`) USING BTREE,
  INDEX `idx_userId`(`userId`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_createTime`(`createTime`) USING BTREE,
  INDEX `idx_supplierId`(`supplierId`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单表' ROW_FORMAT = Dynamic;

