-- ----------------------------
-- Table structure for py_product
-- ----------------------------
DROP TABLE IF EXISTS `py_product`;
CREATE TABLE `py_product`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `supplierId` int(11) DEFAULT NULL COMMENT '供应商ID（为NULL表示平台自营）',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品描述',
  `categoryId` int(11) NOT NULL COMMENT '分类ID',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品牌',
  `mainImage` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主图',
  `galleryImages` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品图片',
  `price` decimal(10, 2) NOT NULL COMMENT '商品价格',
  `originalPrice` decimal(10, 2) DEFAULT NULL COMMENT '原价',
  `stock` int(11) DEFAULT 0 COMMENT '库存数量',
  `sales` int(11) DEFAULT 0 COMMENT '销量',
  `status` int(11) DEFAULT 1 COMMENT '状态：1-上架，0-下架，-1-删除',
  `isHot` int(11) DEFAULT 0 COMMENT '是否热销：1-是，0-否',
  `isNew` int(11) DEFAULT 0 COMMENT '是否新品：1-是，0-否',
  `createTime` datetime(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_categoryId`(`categoryId`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_isHot`(`isHot`) USING BTREE,
  INDEX `idx_isNew`(`isNew`) USING BTREE,
  INDEX `idx_supplierId`(`supplierId`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 151 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品表' ROW_FORMAT = Dynamic;

